 void Start(){data=GameData.Load();save=new SaveSystem(Environment.GetCommandLineArgs().Contains("-workbench-reset-check")?System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../TestResults/ResetSave")):Environment.GetCommandLineArgs().Contains("-workbench-smoke")?System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../TestResults/SmokeSave")):null);Application.targetFrameRate=60;QualitySettings.vSyncCount=0;audioSource.volume=save.Data.settings.effects;
