 public bool Transitioning=>motion!=null&&motion.Busy;
 void RefreshIntro(){string[] texts={"После уроков мы собираемся в мастерской.\nИз деталей и игрушечных механизмов каждый строит своего робота.","У каждого робота есть ядро. Защити его, подключи батарею\nи выбери оружие. Самый большой робот не всегда самый сильный.","Друзья уже ждут у большого стола.\nСобирай, испытывай и пробуй новую тактику!"};T("Intro/StoryText").Set(texts[introPage]);I("Intro/Story").sprite=art.Get("Story/intro_"+(introPage+1).ToString("00"));}
 void RefreshMenu(){for(int i=0;i<10;i++){int count=save.Data.levels[i].stars.Count(x=>x);T("Menu/Level"+i+"/Stars").Set("");for(int star=0;star<5;star++)I("Menu/Level"+i+"/Star"+star).sprite=art.Get("UI/Icons/"+(save.Data.levels[i].stars[star]?"star_gold":"star_empty"));var im=I("Menu/Level"+i);im.color=i==selectedLevel?new Color(1,.9f,.68f):Color.white;}T("Menu/Goals").Set(GoalText(data.levels[selectedLevel],save.Data.levels[selectedLevel].stars));}
 string GoalText(LevelSpec l,bool[] flags){var lines=new List<string>{(l.id+1)+". "+l.title};string[] texts={"Победить","Победить за "+FormatTime(l.targetSeconds),l.goals[0].text,l.goals[1].text,l.goals[2].text};for(int i=0;i<5;i++)lines.Add((flags[i]?"[+] ":"[ ] ")+texts[i]);return string.Join("\n",lines);}
 public void OpenBuilder(){Navigate(OpenBuilderNow);}
 void OpenBuilderNow(){CancelDrag();worldView.Clear();battle=null;bot=null;var stored=save.Data.levels[selectedLevel];build=stored.build==null?new List<Placement>{new Placement{id=0,type=0,x=2,y=2}}:Construction.Copy(stored.build);nextId=build.Count==0?1:build.Max(x=>x.id)+1;selectedArena=stored.arena;SetState(ScreenState.Builder);RefreshBuilder();ShowContextHint();}
 void ShowContextHint(){int[] types={8,6,5,7};string[] hints={"Щит: ПКМ создаёт защиту со стороны прицела на 3 секунды.\nПерезарядка 30 секунд; готовность видна на круге модуля.","Гранатомёт поражает группу деталей взрывом.\nОн тяжёлый: сравните защиту и скорость сборки.","Винтовка стреляет далеко и мощно, но только раз в 3 секунды.\nОна занимает две клетки по вертикали.","Дробовик силён вблизи. Урон быстро падает с расстоянием.\nЛёгкой сборке проще догнать противника."};for(int i=0;i<types.Length;i++)if(data.levels[selectedLevel].inventory[types[i]]>0&&!sessionHintsSeen[types[i]]){sessionHintsSeen[types[i]]=true;save.Data.hintsSeen[types[i]]=true;save.Write();Notify(hints[i]);noticeUntil=Time.unscaledTime+9;break;}}
