 public bool TryStartBattle(){if(Transitioning||State!=ScreenState.Builder)return false;if(dragging!=null){Notify("Сначала завершите перенос детали");return false;}var errors=Construction.Validate(build,data,data.levels[selectedLevel]);if(errors.Count>0){Notify(string.Join(". ",errors));Sound("invalid");return false;}StoreBuild();Navigate(()=>{battle=new BattleModel(data,data.levels[selectedLevel],build,selectedArena,UnityEngine.Random.Range(1,100000));bot=new BotController(battle,data.levels[selectedLevel]);battle.Effect+=(key,p,team)=>{string sound=key.StartsWith("muzzle_")?key.Substring(7):key.StartsWith("break_")?"break":key=="shield_reflect"?"reflect":key=="collision"?"impact":key=="hit_module"||key=="hit_wall"?"impact":key;Sound(sound);};worldView.Begin(battle);accumulator=0;SetState(ScreenState.Battle);RefreshHud();});return true;}
 public void Command(string text){if(Transitioning)return;if(text=="начать бой")TryStartBattle();else if(text=="пауза")Pause();else if(text=="продолжить")Resume();}
 public void Pause(){if(State!=ScreenState.Battle)return;SetState(ScreenState.Pause);}
 public void Resume(){if(State!=ScreenState.Pause)return;SetState(ScreenState.Battle);}
 void EndBattle(){bool won=battle.winner==0;var level=data.levels[selectedLevel];earned=Stars.Evaluate(level,battle.robots[0],battle.robots[1],battle.time,won);Stars.Merge(save.Data.levels[selectedLevel].stars,earned);sessionTutorialDone|=won;save.Data.tutorialDone|=won;save.Write();SetState(ScreenState.Result);
  string[] goals={"Победить","Победить за "+FormatTime(level.targetSeconds),level.goals[0].text,level.goals[1].text,level.goals[2].text};
  for(int star=0;star<5;star++){I("Result/Star"+star).sprite=art.Get("UI/Icons/"+(earned[star]?"star_gold":"star_empty"));T("Result/Goal"+star).Set(goals[star]);}
  T("Result/Level").Set((selectedLevel+1)+". "+level.title);T("Result/Title").Set(won?"ПОБЕДА!":battle.winner<0?"НИЧЬЯ":"ПОРАЖЕНИЕ");T("Result/Summary").Set("Время боя: "+FormatTime(battle.time));T("Result/Saved").Set("Всего звёзд уровня: "+save.Data.levels[selectedLevel].stars.Count(x=>x)+" / 5. Ранее полученные звёзды сохранены.");
  bool next=won&&selectedLevel<9;Obj("Result/Next").gameObject.SetActive(next);Obj("Result").GetComponent<PopupMotion>().SetRestPosition((RectTransform)Obj("Result/Retry"),new Vector2(next?544:720,-712));((RectTransform)Obj("Result/Retry")).sizeDelta=new Vector2(next?380:480,80);((RectTransform)Obj("Result/Retry/Label")).sizeDelta=new Vector2(next?348:448,48);Sound(won?"victory":"defeat");if(won)StartCoroutine(ResultSparkles());
 }
 System.Collections.IEnumerator ResultSparkles(){yield return new WaitForSecondsRealtime(.5f);for(int i=0;i<5;i++)if(earned[i])uiParticles.Burst(new Vector2(568,390+i*56),16,new Color(1,.8f,.3f));}
 public static string FormatTime(float t)=>((int)t/60)+":"+((int)t%60).ToString("00");
 void Update(){if(data==null||save==null)return;
  float aspect=(float)Screen.width/Screen.height;var cam=worldView.worldCamera;if(aspect>16f/9)cam.rect=new Rect((1-16f/9/aspect)*.5f,0,16f/9/aspect,1);else cam.rect=new Rect(0,(1-aspect/(16f/9))*.5f,1,aspect/(16f/9));
  var keyboard=Keyboard.current;var mouse=Mouse.current;if(!Transitioning&&keyboard!=null&&keyboard.escapeKey.wasPressedThisFrame){if(dragging!=null)CancelDrag();else if(State==ScreenState.Battle)Pause();else if(State==ScreenState.Pause)Resume();else if(State==ScreenState.Arenas)SetState(ScreenState.Builder);else if(State==ScreenState.ResetProgress)SetState(ScreenState.Settings);else if(State==ScreenState.Settings){save.Write();recognition.Apply(save.Data.settings);SetState(settingsReturn);}}
  if(State==ScreenState.Builder&&!Transitioning&&mouse!=null&&Time.unscaledTime>=inputBlockedUntil){Vector2 p=MousePoint();if(mouse.leftButton.wasPressedThisFrame)BeginDrag(p,false);if(mouse.leftButton.wasReleasedThisFrame&&!handDrag)Drop(p);if(mouse.rightButton.wasPressedThisFrame){var found=At(p);if(found!=null){build.Remove(found);StoreBuild();RefreshBuilder();Sound("place");}}T("Builder/InputStatus").Set(recognition.VoiceStatus+"\n\n"+recognition.HandStatus);}
  if(dragging!=null){Vector2 p=handDrag?recognition.Pointer:MousePoint();UpdateGhost(p);}
  bool hand=recognition.Tracked&&save.Data.settings.hand;handCursor.gameObject.SetActive(hand);if(hand){handCursor.rectTransform.anchoredPosition=new Vector2(recognition.Pointer.x-32,-recognition.Pointer.y+32);handCursor.sprite=art.Get("UI/Input/gesture_"+(recognition.Pinching?"grab":"open"));}
  if(notice.activeSelf&&Time.unscaledTime>noticeUntil)notice.SetActive(false);if(State==ScreenState.Settings)RefreshSettings();
  if(State!=ScreenState.Battle||battle==null||Transitioning)return;
  var player=battle.robots[0];Vector2 move=Vector2.zero;if(keyboard!=null){if(keyboard.wKey.isPressed)move.y--;if(keyboard.sKey.isPressed)move.y++;if(keyboard.aKey.isPressed)move.x--;if(keyboard.dKey.isPressed)move.x++;}player.move=Vector2.ClampMagnitude(move,1);
  if(mouse!=null){Vector3 point=cam.ScreenToWorldPoint(mouse.position.ReadValue());player.aim=new Vector2(point.x,-point.y);bool ui=EventSystem.current!=null&&EventSystem.current.IsPointerOverGameObject();player.firing=mouse.leftButton.isPressed&&!ui&&Time.unscaledTime>inputBlockedUntil;player.shieldRequested=mouse.rightButton.wasPressedThisFrame&&!ui&&Time.unscaledTime>inputBlockedUntil;}
  accumulator+=Mathf.Min(Time.unscaledDeltaTime,.1f);while(accumulator>=1f/60&&!battle.finished){bot.Tick();BeforeSimulationStep?.Invoke(battle);battle.Step(1f/60);accumulator-=1f/60;}WorldView.Interpolation=Mathf.Clamp01(accumulator*60);RefreshHud();if(battle.finished)EndBattle();
 }
 void RefreshHud(){T("Battle/Timer").Set(FormatTime(battle.time));
  for(int i=0;i<2;i++){var core=battle.robots[i].Core;Obj(i==0?"Battle/PlayerHP":"Battle/EnemyHP").GetComponent<HealthBar>().Set(core.hp/core.maxHp,battle.time,i==1);}
  Obj("Battle/Controls").gameObject.SetActive(save.Data.settings.controlHints);var k=Keyboard.current;if(k!=null){bool[] down={k.wKey.isPressed,k.aKey.isPressed,k.sKey.isPressed,k.dKey.isPressed,k.escapeKey.isPressed};string[] names={"W","A","S","D","Esc"};for(int i=0;i<5;i++)I("Battle/Controls/Key"+i).sprite=art.Get("UI/Input/Keys/"+names[i]+(down[i]?"_down":"_up"));}}
 Vector2 MousePoint(){if(Mouse.current==null)return Vector2.zero;RectTransformUtility.ScreenPointToLocalPointInRectangle(uiRoot,Mouse.current.position.ReadValue(),null,out Vector2 p);var rect=(uiRoot).rect;return new Vector2(p.x-rect.xMin,rect.yMax-p.y);}
