 void BeginDrag(Vector2 point,bool byHand){if(State!=ScreenState.Builder||dragging!=null)return;var placed=At(point);if(placed!=null){dragging=placed.Copy();dragOriginal=placed.Copy();dragOffset=point-new Vector2(800+placed.x*64,244+placed.y*64);build.Remove(placed);selectedType=placed.type;}else for(int i=0;i<9;i++){var rect=BuilderLayout.InventorySlot(i,data.levels[selectedLevel]);if(!rect.Contains(point))continue;selectedType=i;if(build.Count(m=>m.type==i)>=data.levels[selectedLevel].inventory[i]){Sound("invalid");RefreshBuilder();return;}dragging=new Placement{id=nextId++,type=i};dragOriginal=null;dragOffset=new Vector2(data.modules[i].width*32,data.modules[i].height*32);break;}if(dragging!=null){handDrag=byHand;RefreshBuilder();UpdateGhost(point);}}
 void UpdateGhost(Vector2 point){var spec=data.modules[dragging.type];Vector2 top=point-dragOffset;dragging.x=Mathf.RoundToInt((top.x-800)/64);dragging.y=Mathf.RoundToInt((top.y-244)/64);bool over=new Rect(760,204,400,400).Contains(point);if(over)top=new Vector2(800+dragging.x*64,244+dragging.y*64);dragGhost.gameObject.SetActive(true);dragGhost.sprite=art.Get("Modules/Player/"+spec.key);dragGhost.rectTransform.sizeDelta=new Vector2(spec.width*64,spec.height*64);dragGhost.rectTransform.anchoredPosition=new Vector2(top.x,-top.y);dragGhost.color=Construction.TryPlace(build,dragging,dragOriginal,data,out _)?new Color(.8f,1,.8f,.8f):new Color(1,.4f,.4f,.8f);}
 void Drop(Vector2 point){if(dragging==null)return;UpdateGhost(point);if(Construction.TryPlace(build,dragging,dragOriginal,data,out var exchanged)){build=exchanged;Sound("place");uiParticles.Burst(point,12,new Color(.4f,1,.85f));}else if(new Rect(384,800,864,264).Contains(point)){Sound("place");}else{if(dragOriginal!=null)build.Add(dragOriginal);Sound("invalid");Notify("Для обмена не хватает места на поле. Деталь возвращена.");}dragging=null;dragOriginal=null;dragGhost.gameObject.SetActive(false);StoreBuild();RefreshBuilder();}
 public void CancelDrag(){if(dragging==null)return;if(dragOriginal!=null)build.Add(dragOriginal);dragging=null;dragOriginal=null;handButton=null;if(dragGhost)dragGhost.gameObject.SetActive(false);if(data!=null&&save!=null&&State==ScreenState.Builder)RefreshBuilder();}
