 Button ButtonAt(Vector2 p){if(EventSystem.current==null)return null;var results=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=CanvasPoint(p)},results);return results.Count==0?null:results[0].gameObject.GetComponentInParent<Button>();}
