 void RefreshBuilder(){var level=data.levels[selectedLevel];var errors=Construction.Validate(build,data,level);T("Builder/Checks").Set(errors.Count==0?"[+] Ядро установлено\n\n[+] Энергии хватает\n\n[+] Модули соединены":string.Join("\n\n",errors));int consumption=build.Sum(p=>data.modules[p.type].Cost),capacity=build.Count(p=>p.type==3)*5;float mass=build.Sum(p=>data.modules[p.type].mass);float hp=build.Sum(p=>data.modules[p.type].hp),maxMass=0,maxHP=0;for(int i=0;i<9;i++){maxMass+=level.inventory[i]*data.modules[i].mass;maxHP+=level.inventory[i]*data.modules[i].hp;}
  string[] values={consumption+" / "+capacity,mass.ToString("0"),hp.ToString("0"),data.Speed(mass).ToString("0.0")};float[] ratios={capacity>0?(float)consumption/capacity:consumption>0?1:0,mass/Mathf.Max(1,maxMass),hp/Mathf.Max(1,maxHP),data.Speed(mass)/data.balance.speedMax};string[] barKeys={"energy","mass","hp","speed"};
  for(int i=0;i<4;i++){T("Builder/StatValue"+i).Set(values[i]);I("Builder/StatBar"+i).sprite=art.Get("UI/Bars/States/stat_"+barKeys[i]+"/step_"+Mathf.RoundToInt(Mathf.Clamp01(ratios[i])*12).ToString("00"));I("Builder/StatBar"+i).color=i==0&&consumption>capacity?new Color(1,.35f,.35f):Color.white;}

  var s=data.modules[selectedType];T("Builder/CardTitle").Set(s.title.ToUpperInvariant());I("Builder/CardIcon").sprite=art.Get("UI/Builder/ModuleIcons/"+s.key);T("Builder/CardText").Set(s.description+"\n\nHP: "+s.hp+"    Масса: "+s.mass+"\nПитание: "+s.Cost+(s.id==3?"  (+5)":"")+(s.Weapon?"\nВыстрел: "+s.interval.ToString("0.0")+" с\nУрон: "+s.damage+(s.pellets>1?" × "+s.pellets:"")+"\nДальность: "+s.range:"") );
  for(int i=0;i<9;i++){var slot=I("Builder/Slot"+i);slot.gameObject.SetActive(level.inventory[i]>0);if(level.inventory[i]<=0)continue;var rect=BuilderLayout.InventorySlot(i,level);slot.rectTransform.anchoredPosition=new Vector2(rect.x,-rect.y);
   int count=level.inventory[i]-build.Count(p=>p.type==i)-(dragging!=null&&dragging.type==i?1:0);var counter=I("Builder/Slot"+i+"/Count");counter.gameObject.SetActive(count>1);counter.sprite=art.Get("UI/Counters/Counts/count_"+Mathf.Max(0,count).ToString("00"));counter.SetNativeSize();counter.rectTransform.anchoredPosition=new Vector2(116-counter.rectTransform.sizeDelta.x,-88);
   slot.sprite=art.Get("UI/NineSlice/inventory_slot_"+(count<=0?"disabled":selectedType==i?"pressed":"normal"));slot.color=count<=0?new Color(.5f,.5f,.5f):Color.white;I("Builder/Slot"+i+"/Icon").color=count<=0?new Color(.25f,.25f,.25f):Color.white;
  }
  var placed=Obj("Builder/Placed");ClearChildren(placed);DrawLinks(placed,build,false,64,new Vector2(800,244));var reachable=Construction.Reachable(build,data);foreach(var p in build){var spec=data.modules[p.type];var im=UiFactory.Image(placed,art,"Module "+p.id,"Modules/Player/"+spec.key,800+p.x*64,244+p.y*64,spec.width*64,spec.height*64);if(spec.Weapon){int size=spec.id==5||spec.id==6?128:64;UiFactory.Image(im.transform,art,"Turret","Turrets/Player/"+spec.key+"/dir_00",(spec.width*64-size)/2,(spec.height*64-size)/2,size,size);}if(!reachable.Contains(p.id))UiFactory.Image(im.transform,art,"Disconnected","UI/Builder/disconnected_"+(spec.width*64)+"x"+(spec.height*64),0,0,spec.width*64,spec.height*64);}
  I("Builder/Arena/Preview").sprite=art.Get("UI/Builder/Arenas/scheme_"+(selectedArena+1).ToString("00"));T("Builder/Arena/Number").Set("СХЕМА "+(selectedArena+1).ToString("00"));RenderRobotPreview(Obj("Builder/EnemyRobot"),level.enemy,true,24);
  string hint=!build.Any(p=>p.type==3)?"Перетащите батарею из запаса рядом с ядром.":!build.Any(p=>data.modules[p.type].Weapon)?"Добавьте оружие. Соединяйте детали сторонами.":errors.Count>0?"Устраните ошибки слева. Детали можно переставлять.":"Защитите ядро корпусом или бронёй. Когда готовы — СТАРТ.\nПеренос в запас или ПКМ по детали — снять.";if(sessionTutorialDone)hint="";T("Builder/Hint").Set(hint);
 }
 public void RenderRobotPreview(Transform parent,IEnumerable<Placement> parts,bool enemy,float cell){ClearChildren(parent);var list=parts.ToList();if(list.Count==0)return;float minX=list.Min(p=>p.x),minY=list.Min(p=>p.y),w=list.Max(p=>p.x+data.modules[p.type].width)-minX,h=list.Max(p=>p.y+data.modules[p.type].height)-minY;var rect=((RectTransform)parent).rect;cell=Mathf.Min(cell,Mathf.Floor(rect.width/w),Mathf.Floor(rect.height/h));Vector2 offset=new Vector2(Mathf.Round((rect.width-w*cell)/2)-minX*cell,Mathf.Round((rect.height-h*cell)/2)-minY*cell);
  DrawLinks(parent,list,enemy,cell,offset);foreach(var p in list){var spec=data.modules[p.type];var im=UiFactory.Image(parent,art,"Part"+p.id,"Modules/"+(enemy?"Enemy":"Player")+"/"+spec.key,offset.x+p.x*cell,offset.y+p.y*cell,spec.width*cell,spec.height*cell);if(spec.Weapon){float size=(spec.id==5||spec.id==6?2:1)*cell;UiFactory.Image(im.transform,art,"Gun","Turrets/"+(enemy?"Enemy":"Player")+"/"+spec.key+"/dir_00",(spec.width*cell-size)/2,(spec.height*cell-size)/2,size,size);}}
 }
 void DrawLinks(Transform parent,IList<Placement> parts,bool enemy,float cell,Vector2 offset){foreach(var link in Construction.Links(parts,data)){float w=(link.horizontal?24:12)*cell/64,h=(link.horizontal?12:24)*cell/64;UiFactory.Image(parent,art,"Connector","Connectors/"+(enemy?"enemy":"player")+"_"+(link.horizontal?"horizontal":"vertical"),offset.x+link.center.x*cell-w/2,offset.y+link.center.y*cell-h/2,w,h);}}
 static void ClearChildren(Transform parent){foreach(Transform child in parent){child.gameObject.SetActive(false);Destroy(child.gameObject);}}
 public void Notify(string text){notice.SetActive(true);notice.transform.Find("Text").GetComponent<PixelText>().Set(text);noticeUntil=Time.unscaledTime+4;}
 public void Sound(string key){var clip=art.Audio(key);if(clip)audioSource.PlayOneShot(clip);}
 void OnApplicationQuit(){if(save!=null){if(State==ScreenState.Builder)StoreBuild();else save.Write();}}
}
